import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate, continuous time-based staggered easing with custom bounce math

const { fontFamily: interFamily } = loadInter();



export type ComponentNameProps = Record<string, any>;

// Helper to generate the sequence of characters a flap must spin through sequentially (no random cycles)
function getSequence(startChar: string, endChar: string) {
  const digits = "0123456789".split("");
  
  if (startChar === endChar) {
    return [startChar];
  }

  let startIdx = digits.indexOf(startChar);
  let endIdx = digits.indexOf(endChar);

  // If endChar is not a digit, just transition directly
  if (endIdx === -1) {
    return [startChar, endChar];
  }

  // If startChar is not a digit, start cycling from 0
  if (startIdx === -1) {
    const seq = [startChar];
    let currIdx = 0;
    while (digits[currIdx] !== digits[endIdx]) {
      seq.push(digits[currIdx]);
      currIdx = (currIdx + 1) % digits.length;
    }
    seq.push(digits[currIdx]);
    return seq;
  }

  // Both are digits, step sequentially
  const seq = [digits[startIdx]];
  let currIdx = startIdx;
  while (digits[currIdx] !== digits[endIdx]) {
    currIdx = (currIdx + 1) % digits.length;
    seq.push(digits[currIdx]);
  }
  return seq;
}

const HalfDigit: React.FC<{
  char: string;
  half: "top" | "bottom";
  width: number;
  height: number; // This is the half-height
  gap: number;
  radius: number;
  fontSize: number;
  fontFamily: string;
  bgColor: string;
  textColor: string;
}> = ({ char, half, width, height, gap, radius, fontSize, fontFamily, bgColor, textColor }) => {
  const isTop = half === "top";
  
  return (
    <div style={{
      position: "absolute",
      width,
      height,
      overflow: "hidden",
      backgroundColor: bgColor,
      borderRadius: isTop ? `${radius}px ${radius}px 0 0` : `0 0 ${radius}px ${radius}px`,
      top: isTop ? 0 : undefined,
      bottom: !isTop ? 0 : undefined,
      boxShadow: "inset 0 0 1px rgba(255,255,255,0.1)",
    }}>
      <div style={{
        position: "absolute",
        width,
        height: height * 2 + gap,
        top: isTop ? 0 : undefined,
        bottom: !isTop ? 0 : undefined,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        color: textColor,
        fontSize,
        fontFamily,
        fontWeight: 800,
        lineHeight: 1,
      }}>
        {char}
      </div>
      {/* Volumetric shading */}
      <div style={{
        position: "absolute",
        top: 0, left: 0, right: 0, bottom: 0,
        background: isTop 
          ? "linear-gradient(to bottom, rgba(255,255,255,0.08) 0%, rgba(0,0,0,0.3) 100%)"
          : "linear-gradient(to bottom, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0) 100%)",
        pointerEvents: "none",
      }} />
    </div>
  );
};

const FlipDigit: React.FC<{
  currentValue: string;
  nextValue: string;
  progress: number;
  width: number;
  halfHeight: number;
  gap: number;
  radius: number;
  fontSize: number;
  fontFamily: string;
  bgColor: string;
  textColor: string;
}> = ({ currentValue, nextValue, progress, width, halfHeight, gap, radius, fontSize, fontFamily, bgColor, textColor }) => {
  
  const rotation = -180 * progress;
  const commonProps = { width, height: halfHeight, gap, radius, fontSize, fontFamily, bgColor, textColor };

  return (
    <div style={{
      position: "relative",
      width,
      height: halfHeight * 2 + gap,
      perspective: "1200px",
      transformStyle: "preserve-3d",
      backgroundColor: "#0a0a0a", // Backplate behind the gap
      borderRadius: radius,
      boxShadow: "0 10px 30px rgba(0,0,0,0.6)",
    }}>
      {/* Static Background Top */}
      <div style={{ position: "absolute", top: 0, left: 0, width, height: halfHeight, zIndex: 1 }}>
        <HalfDigit char={nextValue} half="top" {...commonProps} />
      </div>

      {/* Static Background Bottom */}
      <div style={{ position: "absolute", bottom: 0, left: 0, width, height: halfHeight, zIndex: 1 }}>
        <HalfDigit char={currentValue} half="bottom" {...commonProps} />
        {/* Shadow cast by falling flap */}
        <div style={{
          position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
          backgroundColor: "black",
          opacity: Math.max(0, (0.5 - Math.abs(progress - 0.5)) * 1.5),
          pointerEvents: "none"
        }} />
      </div>

      {/* Flipping Container */}
      <div style={{
        position: "absolute",
        top: 0,
        left: 0,
        width,
        height: halfHeight,
        zIndex: 2,
        transformOrigin: `center ${halfHeight + gap / 2}px`,
        transform: `rotateX(${rotation}deg)`,
        transformStyle: "preserve-3d",
      }}>
        {/* Front Face (Current Top) */}
        <div style={{
          position: "absolute",
          top: 0, left: 0, width, height: halfHeight,
          backfaceVisibility: "hidden",
          WebkitBackfaceVisibility: "hidden",
        }}>
          <HalfDigit char={currentValue} half="top" {...commonProps} />
          {/* Darkens as it points to the floor */}
          <div style={{
            position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: "black",
            opacity: progress < 0.5 ? progress * 1.5 : 0,
          }} />
        </div>
        
        {/* Back Face (Next Bottom) */}
        <div style={{
          position: "absolute",
          top: 0, left: 0, width, height: halfHeight,
          backfaceVisibility: "hidden",
          WebkitBackfaceVisibility: "hidden",
          transform: "rotateX(180deg)",
        }}>
          <HalfDigit char={nextValue} half="bottom" {...commonProps} />
          {/* Catches light as it swings down */}
          <div style={{
            position: "absolute", top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: "white",
            opacity: Math.max(0, (progress - 0.5) * 0.2),
          }} />
        </div>
      </div>
      
      {/* Side Hinge Details */}
      <div style={{
        position: "absolute", left: -4, top: halfHeight - gap, width: 8, height: gap * 3,
        backgroundColor: "#1a1a1a", borderRadius: 2, zIndex: 3,
        boxShadow: "inset 0 1px 2px rgba(255,255,255,0.2), 0 2px 4px rgba(0,0,0,0.5)"
      }} />
      <div style={{
        position: "absolute", right: -4, top: halfHeight - gap, width: 8, height: gap * 3,
        backgroundColor: "#1a1a1a", borderRadius: 2, zIndex: 3,
        boxShadow: "inset 0 1px 2px rgba(255,255,255,0.2), 0 2px 4px rgba(0,0,0,0.5)"
      }} />
    </div>
  );
};

const FlipSequence: React.FC<{
  sequence: string[];
  framesPerFlip: number;
  width: number;
  halfHeight: number;
  gap: number;
  radius: number;
  fontSize: number;
  fontFamily: string;
  bgColor: string;
  textColor: string;
}> = ({ sequence, framesPerFlip, ...rest }) => {
  const frame = useCurrentFrame();
  const totalFlips = sequence.length - 1;
  
  if (totalFlips <= 0) {
    return <FlipDigit currentValue={sequence[0] || " "} nextValue={sequence[0] || " "} progress={0} {...rest} />;
  }

  const endFrame = totalFlips * framesPerFlip;
  
  const t = interpolate(frame, [0, endFrame], [0, totalFlips], {
    easing: Easing.bezier(0.2, 0.8, 0.2, 1),
    extrapolateRight: "clamp",
  });

  const clampedT = Math.min(t, totalFlips);
  let currentIndex = Math.floor(clampedT);
  let p = clampedT - currentIndex;

  if (currentIndex >= totalFlips) {
    currentIndex = totalFlips - 1;
    p = 1;
  }

  // Custom mechanical bounce easing for each individual flap drop
  const flapEase = (progressVal: number) => {
    if (progressVal < 0.6) {
      return Easing.in(Easing.poly(3))(progressVal / 0.6); 
    } else if (progressVal < 0.8) {
      const tp = (progressVal - 0.6) / 0.2;
      return 1 - 0.15 * Math.sin(tp * Math.PI);
    } else {
      const tp = (progressVal - 0.8) / 0.2;
      return 1 - 0.04 * Math.sin(tp * Math.PI);
    }
  };

  const progress = flapEase(p);
  const N = sequence[currentIndex];
  const N_next = sequence[currentIndex + 1];

  return <FlipDigit currentValue={N} nextValue={N_next} progress={progress} {...rest} />;
};

const Colon: React.FC<{ size: number; color: string }> = ({ size, color }) => {
  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      justifyContent: "center",
      gap: size * 1.5,
      padding: `0 ${size * 0.5}px`,
      height: "100%",
    }}>
      <div style={{ width: size, height: size, backgroundColor: color, borderRadius: size * 0.2, boxShadow: "0 4px 10px rgba(0,0,0,0.5)" }} />
      <div style={{ width: size, height: size, backgroundColor: color, borderRadius: size * 0.2, boxShadow: "0 4px 10px rgba(0,0,0,0.5)" }} />
    </div>
  );
};

const ComponentName: React.FC<ComponentNameProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 4,
  startScore = "12:00",
  endScore = "36:10",
  flapColor = "#1a1a1a",
  textColor = "#ffffff",
}) => {
  const { width, height, durationInFrames } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Align start string to end string length to ensure 1:1 mapping
  const endChars = useMemo(() => endScore.split(""), [endScore]);
  const startChars = useMemo(() => startScore.padStart(endChars.length, " ").split("").slice(-endChars.length), [startScore, endChars.length]);

  const sequences = useMemo(() => {
    return endChars.map((char, i) => {
      if (char === ":") return [":"];
      // Flip sequentially without minimum length padding
      return getSequence(startChars[i], char);
    });
  }, [endChars, startChars]);

  const maxTotalFlips = useMemo(() => Math.max(...sequences.map(s => s.length - 1)), [sequences]);
  const maxEndFrame = Math.max(30, durationInFrames - 30); // leave buffer for rest
  const framesPerFlip = maxEndFrame / Math.max(1, maxTotalFlips);

  // Responsive Layout Math
  const numFlaps = endChars.filter(c => c !== ":").length;
  const numColons = endChars.length - numFlaps;
  
  const flapToWidthRatio = 1;
  const colonToWidthRatio = 0.2;
  const gapToWidthRatio = 0.05; 
  
  const totalRatio = numFlaps * flapToWidthRatio + numColons * colonToWidthRatio + Math.max(0, endChars.length - 1) * gapToWidthRatio;
  
  const maxWFromWidth = (width * 0.85) / totalRatio;
  const maxWFromHeight = (height * 0.65) / 1.6;
  
  const flapWidth = Math.min(maxWFromWidth, maxWFromHeight);
  const flapHeight = flapWidth * 1.6;
  const halfHeight = flapHeight / 2;
  const gap = flapHeight * 0.015;
  const radius = flapWidth * 0.08;
  const fontSize = flapHeight * 0.75;
  const flexGap = flapWidth * gapToWidthRatio;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, justifyContent: "center", alignItems: "center" }}>
      <div style={{
        display: "flex",
        flexDirection: "row",
        alignItems: "center",
        gap: flexGap,
        height: flapHeight + gap,
      }}>
        {endChars.map((char, i) => {
          if (char === ":") {
            return <Colon key={i} size={flapHeight * 0.12} color={flapColor} />;
          }
          
          return (
            <FlipSequence
              key={i}
              sequence={sequences[i]}
              framesPerFlip={framesPerFlip}
              width={flapWidth}
              halfHeight={halfHeight}
              gap={gap}
              radius={radius}
              fontSize={fontSize}
              fontFamily={interFamily}
              bgColor={flapColor}
              textColor={textColor}
            />
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default ComponentName;